/**
 * Golden fixtures for the in-app costing maths (lib/costing/quote-math.ts). tests/fixtures/costing-golden.json was generated by
 * running the REAL Python engine (calc_detailed_quote and to_dict in services/costing-engine/app/services/quoting_enhanced.py on
 * claude/a8-costing-activation 9b98c3f, CPython 3.13) on fixed inputs: every operation shape and optional key, quantities 1 to 1000,
 * scrap, margins 0 to 95%, overhead multipliers, and each tooling, tool-change, in-process inspection, consumables, programming and
 * first-article branch. The port must give, for every case, the same unrounded floats (raw: every dataclass attribute, compared with
 * Object.is) and the same to_dict() output (to the penny, the same float), and pyRound must give CPython's round(x, n) exactly.
 * Skipped while quote-math.ts is the TODO-CHATGPT-PORT stub (it exports QUOTE_MATH_STUB); runs as soon as the port removes it.
 */
import { readFileSync } from "node:fs";
import path from "node:path";

import { describe, expect, it } from "vitest";

import * as quoteMath from "@/lib/costing/quote-math";
import type { DetailedQuoteInput } from "@/lib/costing/quote-math";

type GoldenCase = { name: string; input: DetailedQuoteInput; raw: unknown; dict: unknown };
type Golden = { source: { file: string; commit: string; sha256: string }; cases: GoldenCase[]; py_round: { x: number; n: number; out: number }[] };

const GOLDEN = JSON.parse(readFileSync(path.resolve(__dirname, "../fixtures/costing-golden.json"), "utf8")) as Golden;
const isStub = (quoteMath as { QUOTE_MATH_STUB?: boolean }).QUOTE_MATH_STUB === true;

describe("costing golden fixtures (always)", () => {
  it("come from the real engine file and cover the branches", () => {
    expect(GOLDEN.source.file).toBe("services/costing-engine/app/services/quoting_enhanced.py");
    expect(GOLDEN.source.sha256).toMatch(/^[0-9a-f]{64}$/);
    expect(GOLDEN.cases.length).toBeGreaterThanOrEqual(30);
    const quantities = GOLDEN.cases.map((c) => c.input.quantity);
    expect(Math.min(...quantities)).toBe(1);
    expect(Math.max(...quantities)).toBe(1000);
    const some = (f: (c: GoldenCase) => boolean) => GOLDEN.cases.some(f);
    const anyOp = (key: keyof DetailedQuoteInput["ops"][number]) => some((c) => c.input.ops.some((o) => Number(o[key] ?? 0) > 0));
    expect(some((c) => c.input.ops.length === 0)).toBe(true);
    expect(some((c) => c.input.ops.length >= 4)).toBe(true);
    expect(some((c) => (c.input.programming_time_hr ?? 0) > 0)).toBe(true);
    expect(some((c) => (c.input.first_article_inspection_hr ?? 0) > 0)).toBe(true);
    expect(some((c) => c.input.programming_rate_per_hr === undefined)).toBe(true);
    expect(some((c) => c.input.margin_pct === undefined)).toBe(true);
    expect(some((c) => c.input.margin_pct === 0)).toBe(true);
    expect(some((c) => c.input.scrap_factor === 0) && some((c) => c.input.scrap_factor >= 0.3)).toBe(true);
    for (const key of ["tool_cost_per_part", "tool_change_time_min", "inspection_time_min", "consumables_cost_per_part"] as const) expect(anyOp(key)).toBe(true);
    expect(some((c) => c.input.ops.some((o) => o.operation_type === undefined))).toBe(true);
    expect(GOLDEN.py_round.length).toBeGreaterThan(100);
  });
});

describe.skipIf(isStub)("lib/costing/quote-math.ts matches the Python engine", () => {
  it.each(GOLDEN.py_round.map((r, i) => [i, r] as const))("pyRound case %i", (_i, r) => {
    expect(Object.is(quoteMath.pyRound(r.x, r.n), r.out)).toBe(true);
  });

  it.each(GOLDEN.cases.map((c) => [c.name, c] as const))("%s", (_name, c) => {
    const breakdown = quoteMath.calcDetailedQuote(structuredClone(c.input));
    expect(breakdown).toEqual(c.raw);
    expect(quoteMath.detailedQuoteToDict(breakdown)).toEqual(c.dict);
  });
});
